import Banner from "./Bannner";
import ContactFooter from "./ContactFooter";
import HtmlRenderer from "./HtmlRenderer";
import { Link } from "react-router-dom";
import glv from '../utils/getLocalizedValue'

function Introduce({ name, position, description, imgSrc }) {
  return (
    <>
      <section className="flex sm:flex-row flex-col justify-center sm:items-start items-center w-full font-pretendard my-10 mb-[8rem]">
        <div className="flex h-full sm:mb-0 mb-5 w-[10rem]">
          <img alt="" src={imgSrc} className="w-full object-cover" />
        </div>
        <div className="flex flex-1 flex-col sm:ms-[3rem] flex-wrap mb-5">
          <header className="mb-5 pb-5 border-b-[1px] border-brand-steel-grey">
            <h2 className="me-5">
              <span className="font-[900] f-32">{name && name}</span>
              &nbsp;
              &nbsp;
              <br className="sm:hidden"/>
              <span className="font-[700] f-20 leading-8 text-brand-kool-blue">
                {position && position}
              </span>
            </h2>
          </header>
          <section className="font-[300] f-20 leading-8 text-justify text-[#5F5D59]">
            <HtmlRenderer htmlString={description} />
          </section>
        </div>
      </section>
    </>
  );
}

function Section({ title, summary, content, link, src }) {
  return (
    <>
      <section className="flex flex-wrap justify-center items-center w-full font-pretendard py-[5rem]">
        <header className="text-center mb-10">
          <h2 className="font-[900] f-32">{title && title}</h2>
          <br />
          <span className="font-[700] f-20 leading-8 text-brand-kool-blue">
            {summary && summary}
          </span>
        </header>
        <section className="font-[300] f-20 leading-8 mb-10 text-justify">
          <HtmlRenderer htmlString={content} />
        </section>
        {link && (
          <footer className="font-[700] f-20">
            <Link to={src && src}>
              <span className="underline">{link && link}</span> ➜
            </Link>
          </footer>
        )}
      </section>
    </>
  );
}

function CompanyPage() {
    return (
      <>
        <div className="w-full h-full overflow-y-scroll overflow-x-hidden">
          <Banner
            title={glv("About KoolMicro","KoolMicro 소개")}
            src={require("../assets/about-banner-bg.jpg")}
          />
          <div className="max-w-[70rem] mx-auto px-5 mt-10">
            <Section
              title={glv("Company Introduction","머릿글")}
              summary={"“We make your tomorrow Kool-er.”"}
              content={
                glv("KoolMicro is synonymous with ultimate cooling solutions for microelectronics, delivering innovative technologies designed to meet the demands of next-generation devices. As pioneers in integrating advanced cooling solutions with heterogeneous semiconductor packaging for AI applications, we set the standard for performance and reliability.<br/><br/>Our patented Integrated Manifold MicroChannel technology represents a breakthrough in addressing the thermal and mechanical challenges of cutting-edge semiconductor devices, ensuring optimal efficiency and longevity.<br/><br/>We specialize in custom-tailored cooling solutions for high-performance semiconductors across data centers, automotive systems, and telecommunications, making KoolMicro your trusted partner for advanced thermal management."
                  ,"KoolMicro는 Microelecronics 분야에서 맞춤형 냉각 솔루션 산업의 대표주자로, 차세대 디바이스의 요구를 충족시키기 위해 설계된 혁신적인 기술을 선보입니다. <br/>AI 애플리케이션을 위한 첨단 냉각 솔루션과 이종 반도체 패키징을 통합하는 데 있어 성능과 신뢰성의 기준을 선도하고 있습니다.<br/><br/>KoolMicro의 특허 기술인 IMMC(Integrated Manifold MicroChannel) 기술은 첨단 반도체 장치의 열적·기계적 과제를 해결하는 획기적인 돌파구를 제공하며, 운영 장비 및 칩셋이 최적의 효율성과 장기적인 안정성을 가질수 있도록 보장합니다.<br/><br/>KoolMicro는 첨단 열관리 분야에서 신뢰할 수 있는 파트너로서 데이터센터, 자동차 시스템, 통신 분야 등 필요한 곳 어디든 고성능 반도체를 위한 맞춤형 냉각 솔루션을 전문으로 제공합니다.")}
              link={glv("Click Here for our Latest News and Updates","KoolMicro의 최신 뉴스 및 동향 보러가기")}
              src={"/company/news"}
            />
            <Section
              title={glv("You are in Good Hands","믿고 맡길 수 있는 KoolMicro")}
              summary={glv("Meet the team behind all the magic at KoolMicro","KoolMicro의 모든 혁신을 이끄는 전문가 팀을 소개합니다.")}
              content={
                glv("At KoolMicro, we bring over 25 years of expertise in semiconductor chip architecture and packaging. Our deep understanding of the industry’s challenges allows us to deliver powerful, innovative solutions that exceed expectations. With a team of experts driven by passion and precision, we are committed to providing our customers with the confidence and results they need to succeed in the fast-evolving tech landscape."
                  ,"KoolMicro는 25년 이상의 반도체 칩 아키텍처와 패키징 경험을 바탕으로, 업계의 가장 까다로운 과제를 해결합니다. <br/>깊은 기술 이해와 혁신적 솔루션을 통해 고객이 기대하는 그 이상을 제공합니다. <br/>열정과 실력으로 업계 최고의 기술 발전을 이끄는 전문가 팀이 빠르게 변하는 기술 환경 속에서 고객의 확신과 성과를 보장합니다.")
              }
            />
          </div>
          <div className="max-w-[70rem] mx-auto px-5 mt-10">
            <Introduce
              imgSrc={require("../assets/photo/1.png")}
              name={glv("Yunheok Im","임윤혁")}
              position={"CEO"}
              description={
                glv("<strong class='text-black'>Yunhyeok Im</strong> is a thermal expert with over 24 years of experience in semiconductor chips and related components, gained through his work at Samsung Electronics and Georgia Tech. He has led groundbreaking thermal projects, shaping design decisions by delivering accurate analysis, innovative experiments, and valuable insights for SOC, RF, image sensors, and memory products from the early design stages. With 54 U.S. patents and more than 30 published papers, his contributions to the field are significant. Currently, his research focuses on next-generation liquid cooling and advanced thermal architectures for cutting-edge semiconductor packages. Dr. Im earned his Ph.D. in Mechanical Engineering from KAIST."
                  ,"<strong class='text-black'>임윤혁</strong><br/>KAIST 기계공학 박사 학위와 삼성전자, 조지아 텍에서의 경험을 바탕으로 24년 이상 반도체 칩 및 관련 부품 분야에서 전문성을 쌓아온 Thermal 기술 전문가입니다. 획기적인 열관리 프로젝트를 여럿 이끌며 초기 설계 단계부터 SOC, RF, 이미지 센서, 그리고 메모리 제품에 대한 정확한 분석, 혁신적인 실험, 가치 있는 통찰을 제공해 현재의 설계 기술을 만들었습니다. 54개의 미국 특허와 30편 이상의 논문을 발표한 그는 해당 분야 최전선에서 활동하는 핵심 연구인력 중 1명이며, 현재 차세대 액체 냉각 및 첨단 반도체 패키지를 위한 고급 열 구조에 대한 연구를 집중적으로 진행하고 있습니다. ")
              }
            />
            <Introduce
              imgSrc={require("../assets/photo/2.png")}
              name={glv("Wonyoung Maeng","맹원영")}
              position={"CSO"}
              description={
                glv("<strong class='text-black'>Wonyoung Maeng</strong> is a seasoned expert in strategy, business, and technology planning within the semiconductor industry, with nearly 20 years of experience. He has played a key role in M&A, divestitures, equity investments, and partnerships, making a significant impact in the field. As a former manager at Samsung Electronics, he oversaw the Samsung Strategy Innovation Center and the Catalyst Fund in Silicon Valley, establishing strong networks with global tech leaders. Currently, he leads strategy and operations at KoolMicro, driving business growth through market insights and competitive analysis. He holds degrees in Management Engineering from KAIST and Industrial Engineering from Korea University."
                  ,"<strong class='text-black'>맹원영</strong><br/>KAIST 경영공학 학위, 고려대학교 산업공학 학위를 취득한 이후로 반도체 산업 내 전략, 비즈니스, 기술 계획 분야에서 거진 20년 간의 경력을 자랑하는 전문가입니다. 그는 다수의 M&A, 자산 매각, 지분 투자 및 파트너십에서 중요한 역할을 맡아 왔으며, 삼성 전략 혁신 센터(SSIC)와 실리콘밸리의 Catalyst Fund에서 매니저로 근무하는 동안 글로벌 기술 리더들과 강력한 네트워크를 구축했습니다. 현재 KoolMicro에서 시장 전략 및 운영을 담당하며, 냉정한 시장 통찰과 정확한 경쟁 분석을 통해 최대 성장을 추진하고 있습니다. ")}
            />
            <Introduce
              imgSrc={require("../assets/photo/3.png")}
              name={"James Cooke"}
              position={"Advisor"}
              description={
                glv("<strong class='text-black'>James Cooke</strong> is an experienced executive with over a decade of leadership in advanced materials for the medical and electronics sectors. He has a strong track record in scaling high-growth businesses, managing complex product launches, and navigating the semiconductor and advanced manufacturing industries. As an owner-operator of multiple successful ventures, James excels in operational excellence and strategic decision-making. He serves on the boards of several advanced manufacturing companies and has successfully scaled disruptive startups. James holds a degree in Accounting and Finance from Emory University."
                  ,"<strong class='text-black'>James Cooke</strong><br/>의료 및 전자 분야 첨단 소재에서 10년 이상의 리더십 경험을 가진 전문 경영인입니다. 고성장 비즈니스 확장, 복잡한 제품 출시 관리, 반도체 및 첨단 제조 산업을 탐색하는 데 항상 뛰어난 성과를 보였으며, 여러 성공적인 벤처의 소유자이자 운영자로서 그의 운영 우수성과 탁월한 전략적 의사 결정 능력을 꾸준히 증명하고 있습니다. 에모리 대학교에서 회계학과 금융학 학위를 취득한 뒤로 현재 여러 첨단 제조 회사의 이사회에 재직 중이며, 스타트업들 다수를 혁신과 성공의 유니콘으로 성장시킨 장본인입니다.")
                }
            />
          </div>
          <div className="flex flex-col w-full text-center my-[10rem] sm:scale-100 scale-75">
            {glv(<div>
              <span className="font-pretendard font-[900] f-32">
                Feeling included?
                <br className="sm:hidden" /> Come join the world’s{" "}
                <span className="text-brand-electric-blue">Kool-est</span>{" "}
                family!
              </span>
            </div>,"")}
            <div className="mt-10 bg-brand-electric-blue rounded-full py-3 px-[4rem] w-fit mx-auto">
              <Link to="/career" className="">
                <span className="underline font-[700] f-20">
                  {glv("Click Here to check our Open Positions & Offers","KoolMicro의 채용 공고 및 지원 확인하기")}
                </span>{" "}
                ➜
              </Link>
            </div>
          </div>
          <ContactFooter />
        </div>
      </>
    );
}

export default CompanyPage;